import java.io.PrintWriter;
import java.util.Scanner;

public class Solution {
    static final long MOD = 998244353L;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        long n = sc.nextLong();
        long m = sc.nextLong();
        long l = sc.nextLong();
        long r = sc.nextLong();
        long cells = n * m;

        if ((cells & 1) == 1) {
            out.println(power(r - l + 1, cells));
            out.close();
            return;
        }

        long even = r / 2 - (l - 1) / 2;
        long odd = r - l + 1 - even;

        long ans = (power(even + odd, cells) + power(even - odd, cells)) % MOD;
        ans = ans * power(2, MOD - 2) % MOD;

        out.println(ans);
        out.close();
    }

    static long power(long base, long exp) {
        long result = 1L;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }
}
